  const bacak = (L, k = 1, dy = 0) => L ? L.map(l => 'M' + l.map((q, i) => f1(q[0]) + ' ' + f1(i ? q[1] * k : q[1] + dy)).join('L')).join('') : '';
  // A: uz (uzak kulak/ayak), ub / yb (uzak / yakın bacak çizgileri), gv (siluet), gl (gölge), is (ışık), ak (açık bölge), kk (göz, burun)
  const ust = (L, k = 1, dy = 0) => L ? L.map(l => l.length > 2 ? `M${f1(l[0][0])} ${f1(l[0][1] + dy)}L${f1(l[1][0])} ${f1(l[1][1] * k)}` : '').join('') : '';
